import sys,os
from mir.core.capabilities.manager import CapabilityError
class CapabilityManager:
 def __init__(self,*a,**kw): self.output=sys.stdout; self.output.write('A')
 def sync(self,*a,**kw):
  self.output.write('B')
  raise CapabilityError('refused')
 finalize = sync

